private translate = inject(TranslateService);
private userService = inject(UserService);
private router = inject(Router);

dashboardUser: any = this.userService.getCurrentUser();

authorityName(): string {
    let name: any = "user.anonymous";
    if (this.dashboardUser) {
        const authority: any = this.dashboardUser.authority;
        if (authority === 'SYS_ADMIN') {
            name = 'user.sys-admin';
        } else if (authority === 'TENANT_ADMIN') {
            name = 'user.tenant-admin';
        } else if (authority === 'CUSTOMER_USER') {
            name = 'user.customer';
        }
    }
    return this.translate.instant(name);
}

userDisplayName(): string {
    let name: any = "";
    if (this.dashboardUser) {
        if ((this.dashboardUser.firstName && this.dashboardUser.firstName.length > 0) ||
            (this.dashboardUser.lastName && this.dashboardUser.lastName.length > 0)) {
            if (this.dashboardUser.firstName) {
                name += this.dashboardUser.firstName;
            }
            if (this.dashboardUser.lastName) {
                if (name.length > 0) {
                    name += " ";
                }
                name += this.dashboardUser.lastName;
            }
        } else {
            name = this.dashboardUser.email;
        }
    }
    return name;
}

openProfile(): void {
    this.router.navigate(['/profile']);
}

logout(): void {
    this.userService.logout();
}
